(() => {
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(pointer: fine)');
const board=document.querySelector('#board');let paused=reduced.matches;
try{document.body.classList.toggle('night',localStorage.getItem('auron-night')==='true');}catch{}
const svg=(body,view='0 0 200 200')=>`<svg viewBox="${view}" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round">${body}</svg>`;
const decorations={
 orbit:svg('<circle cx="100" cy="100" r="95" stroke-dasharray="1 6"/><circle cx="100" cy="100" r="86"/><ellipse cx="100" cy="100" rx="99" ry="47" transform="rotate(-35 100 100)"/><path d="M100 0V15M100 185V200M0 100H15M185 100H200"/><circle cx="178" cy="44" r="6" fill="currentColor"/>'),
 crane:svg('<path d="M12 110L91 82L118 13L126 87L191 39L145 116L100 126L71 167L78 115Z" fill="#e4bd8f"/><path d="M12 110L100 126L91 82L126 87L145 116M118 13L100 126M191 39L126 87L100 126M71 167L100 126"/>'),
 botanical:svg('<path d="M98 190Q80 100 111 15"/><path d="M101 160Q51 171 58 129Q94 124 101 160M98 139Q140 145 147 107Q112 98 98 139M97 111Q53 118 63 80Q95 80 97 111M101 83Q138 91 143 55Q113 48 101 83M109 50Q79 53 88 21Q112 26 109 50" fill="#91a17e44"/>'),
 moon:svg('<path d="M128 22A72 72 0 1 0 170 143A68 68 0 0 1 128 22Z" fill="#d5a36a44"/><path d="M154 16V38M143 27H165M175 62V76M168 69H182M54 19V31M48 25H60"/>'),
 compass:svg('<circle cx="100" cy="100" r="86"/><circle cx="100" cy="100" r="77" stroke-dasharray="1 6"/><path d="M100 8V192M8 100H192M38 38L162 162M38 162L162 38" opacity=".45"/><path d="M100 29L116 84L171 100L116 116L100 171L84 116L29 100L84 84Z"/><path d="M100 29V100L84 84ZM171 100H100L116 84ZM100 171V100L116 116ZM29 100H100L84 116Z" fill="currentColor" opacity=".35"/>'),
 constellation:svg('<path d="M12 160L58 92L107 117L153 45L192 70M58 92L69 20M107 117L138 185" stroke-dasharray="3 5"/><g fill="currentColor"><circle cx="12" cy="160" r="3"/><circle cx="58" cy="92" r="4"/><circle cx="107" cy="117" r="3"/><circle cx="153" cy="45" r="5"/><circle cx="192" cy="70" r="2"/><circle cx="69" cy="20" r="2"/><circle cx="138" cy="185" r="3"/></g>'),
 stamp:svg('<circle cx="100" cy="100" r="85" stroke-width="3"/><circle cx="100" cy="100" r="72" stroke-dasharray="2 5"/><path d="M100 46L112 83L151 83L120 106L132 143L100 120L68 143L80 106L49 83L88 83Z"/>'),
 film:`<svg viewBox="0 0 420 110" aria-hidden="true"><rect width="420" height="110" rx="3" fill="#3c332c"/>${Array.from({length:21},(_,i)=>`<path d="M${i*20+4} 4h10v7h-10zM${i*20+4} 99h10v7h-10z" fill="#d7c5a4"/>`).join('')}<image href="assets/collage.jpeg" x="10" y="18" width="126" height="74" preserveAspectRatio="xMidYMid slice"/><image href="assets/portrait.jpeg" x="147" y="18" width="126" height="74" preserveAspectRatio="xMidYMid slice"/><image href="assets/hit.jpeg" x="284" y="18" width="126" height="74" preserveAspectRatio="xMidYMid slice"/></svg>`,washi:''
};
for(const [name,markup]of Object.entries(decorations)){const d=document.createElement('div');d.className='decoration '+name;d.setAttribute('aria-hidden','true');d.innerHTML=markup;board.append(d);}
const tools=document.createElement('div');tools.className='visual-controls';tools.innerHTML=`<button id="night-toggle" aria-label="Toggle night palette" aria-pressed="${document.body.classList.contains('night')}">${svg('<path d="M15 3A8 8 0 1 0 21 15A8 8 0 0 1 15 3Z"/>','0 0 24 24')}</button><button id="effects-toggle" aria-label="Toggle animation" aria-pressed="${!paused}">${svg('<path d="M12 2L14.5 9.5L22 12L14.5 14.5L12 22L9.5 14.5L2 12L9.5 9.5ZM20 2V6M18 4H22"/>','0 0 24 24')}</button>`;document.body.append(tools);
document.querySelector('#night-toggle').onclick=e=>{const night=document.body.classList.toggle('night');e.currentTarget.setAttribute('aria-pressed',night);try{localStorage.setItem('auron-night',night);}catch{}};
document.body.classList.toggle('effects-paused',paused);
const canvas=document.createElement('canvas');canvas.id='atmosphere';canvas.setAttribute('aria-hidden','true');document.body.append(canvas);const ctx=canvas.getContext('2d');let width=innerWidth,height=innerHeight,frame=0,particles=[],lastPointer=0;
function resize(){width=innerWidth;height=innerHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;canvas.style.width=width+'px';canvas.style.height=height+'px';ctx.setTransform(dpr,0,0,dpr,0,0);}
resize();window.addEventListener('resize',resize);
const stars=Array.from({length:38},()=>({x:Math.random(),y:Math.random(),size:.5+Math.random()*1.4,phase:Math.random()*6.28,speed:.03+Math.random()*.05}));
function loop(time){frame=0;if(paused||document.hidden)return;ctx.clearRect(0,0,width,height);const night=document.body.classList.contains('night');
 for(const s of stars){const alpha=(night?.35:.13)+Math.sin(time*.0006+s.phase)*(night?.22:.08);ctx.fillStyle=`rgba(${night?'244,212,162':'171,119,61'},${alpha})`;ctx.beginPath();ctx.arc((s.x*width+time*s.speed*.015)%width,(s.y*height-time*s.speed*.008+height*100)%height,s.size,0,Math.PI*2);ctx.fill();}
 for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.012;p.life-=.022;const r=p.life*p.size;ctx.globalAlpha=Math.max(0,p.life);ctx.strokeStyle=night?'#f1c997':'#b98451';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(p.x-r,p.y);ctx.lineTo(p.x+r,p.y);ctx.moveTo(p.x,p.y-r);ctx.lineTo(p.x,p.y+r);ctx.stroke();}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);
 if(night){const cycle=time%15000;if(cycle<950){const t=cycle/950;ctx.strokeStyle=`rgba(255,221,173,${Math.sin(t*Math.PI)*.5})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(width*(.2+t*.55),height*(.1+t*.25));ctx.lineTo(width*(.2+t*.55)-65,height*(.1+t*.25)-30);ctx.stroke();}}
 frame=requestAnimationFrame(loop);
}
function start(){if(!frame&&!paused&&!document.hidden)frame=requestAnimationFrame(loop);}
document.querySelector('#effects-toggle').onclick=e=>{paused=!paused;document.body.classList.toggle('effects-paused',paused);e.currentTarget.setAttribute('aria-pressed',!paused);if(paused){cancelAnimationFrame(frame);frame=0;ctx.clearRect(0,0,width,height);}else start();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0;}else start();});reduced.addEventListener('change',()=>{paused=reduced.matches;document.body.classList.toggle('effects-paused',paused);document.querySelector('#effects-toggle').setAttribute('aria-pressed',!paused);if(paused){cancelAnimationFrame(frame);frame=0;ctx.clearRect(0,0,width,height);}else start();});start();
document.addEventListener('pointermove',e=>{if(paused||!fine.matches||e.buttons||performance.now()-lastPointer<48)return;lastPointer=performance.now();if(particles.length<65)particles.push({x:e.clientX,y:e.clientY,vx:(Math.random()-.5)*.35,vy:-.3,life:1,size:1.5+Math.random()*2});});
document.querySelector('#viewport').addEventListener('dblclick',e=>{if(paused||e.target.closest('a,button,.polaroid'))return;for(let i=0;i<20;i++){const a=i*Math.PI/10;particles.push({x:e.clientX,y:e.clientY,vx:Math.cos(a)*(1+Math.random()*2),vy:Math.sin(a)*(1+Math.random()*2),life:1,size:2+Math.random()*2});}});
board.addEventListener('pointermove',e=>{if(!fine.matches||paused||e.buttons)return;const card=e.target.closest('.project');if(!card)return;const r=card.getBoundingClientRect(),px=(e.clientX-r.left)/r.width,py=(e.clientY-r.top)/r.height;card.style.setProperty('--rx',(py-.5)*-5+'deg');card.style.setProperty('--ry',(px-.5)*6+'deg');card.style.setProperty('--mx',px*100+'%');card.style.setProperty('--my',py*100+'%');});
board.addEventListener('pointerout',e=>{const card=e.target.closest('.project');if(card&&!card.contains(e.relatedTarget)){card.style.removeProperty('--rx');card.style.removeProperty('--ry');}});
const photo=document.createElement('dialog');photo.id='photo-viewer';photo.setAttribute('aria-label','Image preview');photo.innerHTML='<button aria-label="Close image preview">×</button><img alt="">';document.body.append(photo);photo.querySelector('button').onclick=()=>photo.close();photo.addEventListener('click',e=>{if(e.target===photo)photo.close();});
document.querySelectorAll('.polaroid').forEach(figure=>{figure.tabIndex=0;figure.setAttribute('role','button');figure.setAttribute('aria-label','Enlarge '+figure.querySelector('img').alt);const open=()=>{const image=figure.querySelector('img'),target=photo.querySelector('img');target.src=image.src;target.alt=image.alt;photo.showModal();};figure.addEventListener('click',open);figure.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});
const map=document.createElement('button');map.id='atlas-map';map.setAttribute('aria-label','Navigate the scrapbook map');map.innerHTML='<svg viewBox="0 0 2600 2450" aria-hidden="true"><g id="map-cards"></g><rect class="map-window" width="0" height="0"/></svg>';document.body.append(map);let camera=null;
function drawMap(){const cards=map.querySelector('#map-cards');cards.innerHTML=[...board.querySelectorAll('.project,.about,.polaroid,.coffee')].map(e=>`<rect class="${e.classList.contains('about')?'map-home':'map-card'}" x="${parseFloat(e.style.left)}" y="${parseFloat(e.style.top)}" width="${e.offsetWidth}" height="${e.offsetHeight}" rx="20"/>`).join('');}
document.addEventListener('portfolio:camera',e=>{camera=e.detail;const r=map.querySelector('.map-window');r.setAttribute('x',-camera.x/camera.scale);r.setAttribute('y',-camera.y/camera.scale);r.setAttribute('width',innerWidth/camera.scale);r.setAttribute('height',innerHeight/camera.scale);});
map.addEventListener('click',e=>{if(!camera)return;const r=map.querySelector('svg').getBoundingClientRect();document.dispatchEvent(new CustomEvent('portfolio:navigate',{detail:{cx:(e.clientX-r.left)/r.width*2600,cy:(e.clientY-r.top)/r.height*2450}}));});map.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();document.querySelector('#overview').click();}});
document.addEventListener('portfolio:ready',drawMap);if(board.dataset.ready)drawMap();
})();
